"use client";

import { useState, useEffect } from "react";
import {
  AlertCircle,
  Loader2,
  UserCircle,
  CheckCircle,
  XCircle,
  Calendar,
} from "lucide-react";
import axios from "axios";
import Layout from "../Layout";

export default function AbsenceRequests() {
  const [requests, setRequests] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    fetchPendingAbsences();
  }, []);

  const fetchPendingAbsences = async () => {
    setIsLoading(true);
    setError("");
    const token = localStorage.getItem("token");

    if (!token) {
      setError("Authentication required. Please log in.");
      setIsLoading(false);
      return;
    }

    try {
      const response = await axios.get(`${process.env.REACT_APP_API_URL}/api/absence/pending`, {
        headers: {
          Authorization: `Bearer ${token}`,
          Role: "Deputydirector",
        },
      });
      if (response.data.success) {
        setRequests(response.data.data);
      } else {
        setError("Failed to fetch absence requests: " + response.data.message);
      }
    } catch (err) {
      setError(`Error fetching absence requests: ${err.response?.data?.message || err.message}`);
      console.error("Fetch absence requests error:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleRequest = async (absenceId, action) => {
    try {
      const token = localStorage.getItem("token");
      const response = await axios.post(
        `${process.env.REACT_APP_API_URL}/api/absence/handle`,
        { absenceId, action },
        {
          headers: {
            Authorization: `Bearer ${token}`,
            Role: "Deputydirector",
          },
        }
      );

      if (response.data.success) {
        setRequests(requests.filter((req) => req._id !== absenceId)); // Remove handled request from list
      } else {
        setError(`Failed to ${action} request: ${response.data.message}`);
      }
    } catch (err) {
      setError(`Error handling request: ${err.response?.data?.message || err.message}`);
    }
  };

  return (
    <Layout>
      <div className="max-w-7xl mx-auto">
        <div className="bg-white rounded-xl shadow-lg overflow-hidden border border-[#C8A45D/30]/50">
          <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white p-6">
            <h1 className="text-2xl font-bold tracking-tight">Absence Requests Management</h1>
            <p className="text-white/80 mt-1">Examiner et approuver/rejeter les demandes d'absence des stagiaires</p>
          </div>

          {error && (
            <div className="m-6 p-4 bg-red-50 border-l-4 border-red-500 flex items-center gap-3 rounded-r-md shadow-sm">
              <AlertCircle className="h-5 w-5 text-red-500 flex-shrink-0" />
              <p className="text-red-700">{error}</p>
            </div>
          )}

          {isLoading ? (
            <div className="flex justify-center items-center h-64">
              <div className="flex flex-col items-center gap-2">
                <Loader2 className="h-8 w-8 text-[#00717F] animate-spin" />
                <p className="text-gray-500">Loading absence requests...</p>
              </div>
            </div>
          ) : requests.length === 0 ? (
            <div className="flex flex-col justify-center items-center h-64 text-gray-500">
              <UserCircle className="h-16 w-16 text-gray-300 mb-2" />
              <p className="mb-2">No pending absence requests</p>
            </div>
          ) : (
            <div className="overflow-x-auto p-6">
              <table className="min-w-full divide-y divide-[#C8A45D/30]/50">
                <thead className="bg-[#F5F6FA]">
                  <tr>
                    <th className="py-3.5 px-4 text-left text-xs font-medium text-[#00717F] uppercase tracking-wider">
                      Interne
                    </th>
                    <th className="py-3.5 px-4 text-left text-xs font-medium text-[#00717F] uppercase tracking-wider">
                      Date de début
                    </th>
                    <th className="py-3.5 px-4 text-left text-xs font-medium text-[#00717F] uppercase tracking-wider">
                      Date de fin
                    </th>
                    <th className="py-3.5 px-4 text-left text-xs font-medium text-[#00717F] uppercase tracking-wider">
                      Reason
                    </th>
                    <th className="py-3.5 px-4 text-left text-xs font-medium text-[#00717F] uppercase tracking-wider">
                      Actions
                    </th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-[#C8A45D/30]/30">
                  {requests.map((request) => (
                    <tr key={request._id} className="hover:bg-[#F5F6FA]/50 transition-colors">
                      <td className="py-4 px-4">
                        <div className="flex items-center">
                          <div className="h-9 w-9 rounded-full bg-gradient-to-r from-[#00717F] to-[#C8A45D]/10 flex items-center justify-center text-[#00717F] mr-3 shadow-sm">
                            <UserCircle className="h-5 w-5" />
                          </div>
                          <div className="text-sm font-medium text-gray-900">
                            {request.stagerName} ({request.internId?.emplacement})
                          </div>
                        </div>
                      </td>
                      <td className="py-4 px-4 text-sm text-#333333">
                        <div className="flex items-center gap-2">
                          <Calendar className="h-4 w-4 text-[#00717F]/60" />
                          {new Date(request.startDate).toLocaleDateString()}
                        </div>
                      </td>
                      <td className="py-4 px-4 text-sm text-#333333">
                        <div className="flex items-center gap-2">
                          <Calendar className="h-4 w-4 text-[#00717F]/60" />
                          {new Date(request.endDate).toLocaleDateString()}
                        </div>
                      </td>
                      <td className="py-4 px-4 text-sm text-#333333">{request.reason}</td>
                      <td className="py-4 px-4 text-sm text-#333333">
                        <div className="flex items-center gap-2 justify-end">
                          <button
                            onClick={() => handleRequest(request._id, 'approve')}
                            className="p-2 text-green-600 hover:bg-green-50 rounded-full transition-colors shadow-sm"
                            aria-label="Approve request"
                          >
                            <CheckCircle className="h-5 w-5" />
                          </button>
                          <button
                            onClick={() => handleRequest(request._id, 'reject')}
                            className="p-2 text-red-600 hover:bg-red-50 rounded-full transition-colors shadow-sm"
                            aria-label="Reject request"
                          >
                            <XCircle className="h-5 w-5" />
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </Layout>
  );
}
